import{_ as t,o as i,c as n,a3 as r}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Heizöl to MQTT","text":"Heizölpreise für Home Assistant","tagline":"Öffentliche Preisrechner von Esyoil und Heizöl24 abfragen und Bestpreise sowie Anbieter-Angebote per MQTT Discovery veröffentlichen.","actions":[{"theme":"brand","text":"Installation","link":"/projects/heizoel-to-mqtt/installation"},{"theme":"alt","text":"GitHub","link":"https://github.com/rockbaer2007/heizoel-to-mqtt"}]},"features":[{"icon":"🛢️","title":"Heizölpreise","details":"Bestpreise für konfigurierte Postleitzahl, Menge und Lieferoptionen abrufen."},{"icon":"📍","title":"Deutschland und Österreich","details":"Preisabfragen für deutsche und österreichische Postleitzahlen."},{"icon":"🧾","title":"Anbieter-Angebote","details":"Bis zu sechs Anbieter-Angebote pro Quelle und Menge mit Preis pro Liter, Preis pro 100 Liter und Gesamtpreis."},{"icon":"🔎","title":"Esyoil und Heizöl24","details":"Öffentliche Preisrechner-Endpunkte werden abgefragt und normalisiert."},{"icon":"🏠","title":"MQTT Discovery","details":"Home Assistant legt Preis-, Anbieter- und Status-Entitäten automatisch an."},{"icon":"🧰","title":"Diagnose","details":"Optionales maskiertes Provider-Logging für Tests und Fehlersuche."}]},"headers":[],"relativePath":"projects/heizoel-to-mqtt/index.md","filePath":"projects/heizoel-to-mqtt/index.md","lastUpdated":1792852622000}'),s={name:"projects/heizoel-to-mqtt/index.md"};function a(o,e,l,d,u,c){return i(),n("div",null,[...e[0]||(e[0]=[r('<h2 id="uberblick" tabindex="-1">Überblick <a class="header-anchor" href="#uberblick" aria-label="Permalink to &quot;Überblick&quot;">​</a></h2><p>Heizöl to MQTT ist eine Home-Assistant-App, die Heizölpreise per MQTT Discovery in Home Assistant bereitstellt.</p><p>Die App fragt öffentliche Preisrechner-Endpunkte ab und normalisiert die besten Angebote pro Quelle und Liter-Menge. Sie ist nur für Deutschland und Österreich vorgesehen.</p><div class="info custom-block"><p class="custom-block-title">Ursprung</p><p>Die Umsetzung ist adaptiert von und inspiriert durch den ioBroker-Adapter <a href="https://github.com/TA2k/ioBroker.heizoel" target="_blank" rel="noreferrer">TA2k/ioBroker.heizoel</a>.</p></div><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Die App ist in Home Assistant testbar und liefert Werte per MQTT Discovery. Unterstützt werden Bestpreis-Entitäten sowie bis zu sechs Anbieter-Angebote pro Quelle und Menge.</p><p>Die genutzten Preis-Endpunkte sind öffentliche Webseiten-Endpunkte und keine offiziell stabil dokumentierten APIs.</p><h2 id="weitere-seiten" tabindex="-1">Weitere Seiten <a class="header-anchor" href="#weitere-seiten" aria-label="Permalink to &quot;Weitere Seiten&quot;">​</a></h2><ul><li><a href="./installation">Installation</a></li><li><a href="./konfiguration">Konfiguration</a></li><li><a href="./entitaeten">Entitäten</a></li><li><a href="./beispiele">Beispiele</a></li></ul>',9)])])}const f=t(s,[["render",a]]);export{h as __pageData,f as default};
